use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        // The output has the same length as the input
        result.len() == a.len(),
    ensures
        // For every valid index i, the elements agree
        forall |i: usize| i < a.len() ==> result[i] == a[i]
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            // we never run past the end
            i <= a.len(),
            // we've copied exactly `i` elements so far
            result.len() == i,
            // and they agree with `a`
            forall |j: usize| j < i ==> result[j] == a[j],
        decreases
            // for termination
            a.len() - i,
    {
        // copy element i
        let x: T = a[i];
        result.push(x);
        i = i + 1;
    }
    result
}

}
